package no.jib.nattcup.domain;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Base64;

public class NCLib {
	private String logodata = "";
	private String logodata2 = "";

	public BufferedImage getLogo() throws IOException {
		StringBuffer SB = new StringBuffer();
		SB.append(logodata);
		SB.append(logodata2);
		byte[] imageBytes = Base64.getDecoder().decode(SB.toString());
		BufferedImage imgtmp = ImageIO.read(new ByteArrayInputStream(imageBytes));
		return imgtmp;
	}

	public byte[] getLogoBytes() {
		byte[] imageBytes = Base64.getDecoder().decode(logodata);
		return imageBytes;
	}
}
